"""Build the independently researched PSY contribution; no network or external writes."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent

def save(name,obj):
    (P/name).write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')

def src(n,title,authors,year,url,kind,access,locator,limit,lineage,**extra):
    return dict(id=f'PSY-S{n:02}',title=title,authors=authors,year=year,url=url,source_type=kind,access=access,locator=locator,scope_limit=limit,evidence_lineage=lineage,accessed='2026-11-05',**extra)

sources=[
 src(1,'Nudging Farmers to Use Fertilizer: Theory and Experimental Evidence from Kenya',['Esther Duflo','Michael Kremer','Jonathan Robinson'],2011,'https://www.atai-research.org/wp-content/uploads/2016/07/aer-Nudging-Fertilizer-2011.pdf','original field experiment and economic model','full-text','AER 101(6), pp.2350–2390; inspected §III–IV, Tables 3–4, §VI and Table 6, particularly pp.2366–2377, 2383–2387.','Parents sampled through 16 Busia schools; household any-plot use is not purchaser-only use. Present bias is a proposed mechanism; welfare comparisons are model calibrations.','Original 2003–05 SAFI experiment and earlier pilots with ICS; related Busia agronomic trials in S02. Programme population and team overlap; not independent replication.',local_file='cache/S01.pdf'),
 src(2,'How High Are Rates of Return to Fertilizer? Evidence from Field Experiments in Kenya',['Esther Duflo','Michael Kremer','Jonathan Robinson'],2008,'https://poverty-action.org/sites/default/files/publications/How%20High%20are%20Rates%20of%20Return%20to%20Fertilizer.pdf','original on-farm experiment','full-text','AER Papers and Proceedings 98(2), pp.482–488; entire short paper, especially research design and Tables 1–2.','Research-assisted small plots and calculated net returns, not nationwide expected profits. Dose, labour assumptions and stochastic yields matter.','Six on-farm experimental seasons beginning July 2000 in Busia; original plot measurements. Related research programme to S01, with some prior-participant pilots carried forward.',local_file='cache/S02.pdf'),
 src(3,'Learning Through Noticing: Theory and Evidence from a Field Experiment',['Rema Hanna','Sendhil Mullainathan','Joshua Schwartzstein'],2014,'https://www.hbs.edu/ris/Publication%20Files/Learning%20Through%20Noticing%20Field%202014_c1214d62-9429-4357-b47a-4195dae00881.pdf','original field experiment and learning model','full-text','QJE 129(3), pp.1311–1353; §III, Tables II–V, §IV.C, footnotes 23–29; pp.1325–1342.','489 experienced farmers from seven Indonesian villages; 117 trial participants; short follow-up. Trial then explanation are sequential, not separate randomisations.','Original 2006 census and 2007–08 seaweed surveys, plot trials and enumerator measures. September 2012 NBER draft also downloaded but final 2014 version used; those versions are one evidence lineage.',local_file='cache/S03.pdf'),
 src(4,'Can Network Theory-based Targeting Increase Technology Adoption? (January 2021 author manuscript)',['Lori Beaman','Ariel BenYishay','Jeremy Magruder','Ahmed Mushfiq Mobarak'],2021,'https://faculty.wcas.northwestern.edu/~lab823/BBMM_Jan2021.pdf','original cluster field experiment; author manuscript','full-text','January 2021 manuscript, §§2–5 and Appendix A; pp.5–15, results tables and mechanism discussion; published AER DOI 10.1257/aer.20200295.','Manuscript inspected, not publisher typeset edition. Three semi-arid districts; 2–3 observed seasons. Centrality is changed with selection, and exact contagion process remains underdetermined.','Original 200-village network census and 2011–13 household surveys; same research network and extension partner as S05–S06, but separate experimental design. Community overlap across trials was not independently crosschecked.',local_file='cache/S04.pdf'),
 src(5,'Social Learning and Incentives for Experimentation and Communication',['Ariel BenYishay','Ahmed Mushfiq Mobarak'],2019,'https://spinup-000d1a-wp-offload-media.s3.amazonaws.com/faculty/wp-content/uploads/sites/45/2021/11/Benyishay_Mobarak_Malawi.pdf','original cluster field experiment','full-text','Public copyedited advance-2018 version, Review of Economic Studies, DOI 10.1093/restud/rdy039; §§2,4–8, Tables 1–2 and 5–7; pp.4–8, outcomes and labour analysis.','120-village analytic experiment; one lead farmer versus five peers confounds communicator identity and number. Distinguish pit planting and crop-residue management.','Original Malawi 2009–11 extension experiment; overlapping cross-cutting assignments and some shared observations with S06. Gender-reserved villages excluded from this paper’s analytic subset; S06 §2.7 states this explicitly.',local_file='cache/S05.pdf'),
 src(6,'Gender Gaps in Technology Diffusion (public author manuscript)',['Ariel BenYishay','Maria Jones','Florence Kondylis','Ahmed Mushfiq Mobarak'],2019,'https://spinup-000d1a-wp-offload-media.s3.amazonaws.com/faculty/wp-content/uploads/sites/45/2019/10/GenderMalawi.pdf','original cluster field experiment; author manuscript','full-text','Author manuscript available at October 2019 path; §§2.7,3,4,5; Tables 3–7, especially pp.11–21. Later published in Journal of Development Economics.','Female-reserved versus unreserved communicator roles, not randomly assigning sex to otherwise identical people. Perceptions measured independently of uptake; pooled adoption/yield gaps imprecise and female-recipient subgroup gaps remain.','Original 143-village Malawi 2009–11 data; same larger experiment as S05, with overlapping unreserved villages and different analytic samples. Cross-cutting treatment interactions not powered.',local_file='cache/S06.pdf'),
 src(7,'The Effects of Service-Delivery Model and Purchase Price on Hearing-Aid Outcomes in Older Adults: A Randomized Double-Blind Placebo-Controlled Clinical Trial',['Larry E. Humes','Sara E. Rogers','Tera M. Quigley','Anna K. Main','Dana L. Kinney','Christine Herring'],2017,'https://pmc.ncbi.nlm.nih.gov/articles/PMC5597084/','original randomised clinical trial with nonrandom price cohorts','full-text','Methods: trial design, participants, outcome measures; Results: service delivery, maintenance, decision to keep and extension; Figures 6–10, 12–14 and Table 5.','163 volunteers, 154 completers; mostly White, educated and relatively affluent, no prior hearing aid use. Service assignment randomised; prices sequential. Post-trial fitting extension not an independently randomised contrast. Apply S13 correction.','Original Indiana University single-site trial, 2 November 2012–31 August 2016; same participants for benefits, satisfaction, datalogged use and returns. S13 corrects its speech-test calibration; it is not independent corroboration.',local_file='cache/S07.html'),
 src(8,'Differences Between Older Adults Who Do and Do Not Try Hearing Aids and Between Those Who Keep and Return the Devices',['Larry E. Humes'],2021,'https://pmc.ncbi.nlm.nih.gov/articles/PMC8182629/','original observational analysis of research volunteers','full-text','Methods: Participants (2004–08 recruitment); Results: adherents/nonadherents and keep/return comparisons; Tables and Discussion.','139 first-time-user analytic participants selected from a larger recruitment pool; only 34 nonpurchasers completed comparison measures. Associations adjusted for hearing loss are not randomised belief effects.','Reanalysis of original Indiana 2004–08 hearing-aid outcome study, parts reported in 2009/2010. Different cohort from S07; those earlier reports were not separately inspected.',local_file='cache/S08.html'),
 src(9,'The Stigma of Hearing Loss',['Margaret I. Wallhagen'],2010,'https://pmc.ncbi.nlm.nih.gov/articles/PMC2904535/','original longitudinal qualitative study','full-text','Methods; Results themes: altered self-perception, ageism, vanity, supportive/nonsupportive others; contrary cases and Discussion.','91 help-seeking Bay Area dyads, 90% White hearing-impaired participants; nonrepresentative. Interviews elicit meanings and attributed reasons; they do not identify a population causal effect of stigma. Field dates not specified in inspected text.','Original separately conducted interviews with each dyad member at baseline, three and twelve months (91,87,84 dyads). Marketing and laboratory sources cited by this paper were not independently inspected or adopted as empirical findings.',local_file='cache/S09.html'),
 src(10,'Cycling to School: Increasing Secondary School Enrollment for Girls in India',['Karthik Muralidharan','Nishith Prakash'],2017,'https://econweb.ucsd.edu/~kamurali/papers/Published%20Articles/Publisher%20Formatted%20Versions/Cycling%20to%20School%20%28AEJ%20Applied%202017%29.pdf','original quasi-experimental programme evaluation','full-text','AEJ Applied Economics 9(3), pp.321–350; programme §I; data/design §§II–III; Table 2, distance analysis, Table 8 placebo; pp.326–345.','Bihar programme exposure, age-appropriate grade-9 enrolment/completion, not individual riding or broad lifetime education. Triple difference depends on trends; norms and safety channels not separately identified.','Original analysis of DLHS-3 2007–08, earlier school enrolment records and exam records. Implementation/leakage evidence in Ghatak et al. is inherited here, not an independently inspected record. S12 reuses this policy and main survey lineage.',local_file='cache/S10.pdf'),
 src(11,'Wheels of Change: Transforming Girls’ Lives with Bicycles (7 May 2025 author manuscript)',['Nathan Fiala','Ana Garcia-Hernandez','Kritika Narula','Nishith Prakash'],2025,'https://www.nishithprakash.com/s/Wheels_of_Change.pdf','original cluster field experiment; author manuscript','full-text','7 May 2025 manuscript, §§3–6 and Appendix B; Tables 1–6, A.4 and A.11; pp.8–24,38–43,56,74–75.','100 public basic schools in three Zambian districts; initially enrolled grade5–7 girls walking >3km. Urban and some very remote schools excluded; disability/cycling-ability representation and route accessibility not established. Survey attrition differs across arms; later administrative outcomes not preregistered. Pooled aspirations imprecise in Tables3/A.11, despite positive wording in the manuscript and final S14 abstracts. Final tables/definitions not inspected; discrepancy unresolved.','Original 2017–18 trial survey plus 2019–21 administrative follow-up collected with implementing partner WBR; 2022 draft preserved separately. Same evidence lineage as final article S14. Programme includes mechanics, monitoring and use restrictions; not a bare bicycle transfer.',local_file='cache/S11.pdf'),
 src(12,'Infrastructure and Girls’ Education: Bicycles, Roads, and the Gender Education Gap in India',['Moritz Seebacher'],2022,'https://www.ifo.de/DocDL/wp-2022-382-seebacher-gender-education-gap-india.pdf','original quasi-experimental reanalysis; working paper','full-text','ifo Working Paper 382, November 2022; §§2–4, road-variable construction pp.4–5, identification cautions pp.9–10, Tables 3–4.','All-weather road to health facilities proxies road access to school; missing road indicator does not mean no road. Road access not randomised. Null coefficient outside connected villages cannot establish strict necessity.','Reuses Bihar bicycle programme and DLHS-3 2007–08 central to S10; adds DLHS-2 pretrend evidence and road heterogeneity. Not an independent policy replication.',local_file='cache/S12.pdf'),
 src(13,'Erratum: Hearing-aid clinical trials and Connected Speech Test calibration',['American Speech-Language-Hearing Association; correction to Humes et al.'],2019,'https://pmc.ncbi.nlm.nih.gov/articles/PMC6808309/','original published correction','full-text','American Journal of Audiology 28(3):730, DOI 10.1044/2019_AJA-19-0087; full correction.','Corrects signal-to-noise ratio from +3 to +1 dB. Authors expect relative benefit to be little affected, but this was not independently recomputed.','Correction to S07 and Humes et al. 2019 follow-up (latter not included as a separately analysed study). Same underlying tests; no independent replication.',local_file='cache/S13.html'),
 src(14,'Wheels of Change: Transforming Girls’ Lives with Bicycles (final journal abstract and metadata)',['Nathan Fiala','Ana Garcia-Hernandez','Kritika Narula','Nishith Prakash'],2026,'https://doi.org/10.1093/ej/ueaf122','final journal article, abstract inspected','abstract','Economic Journal 136(679), October 2026, pp.2531–2561; online publication 8 November 2025; abstract and publication metadata.','Final full text not acquired. Abstract reports rounded34% commute/29% absenteeism reductions and says educational aspirations improved. That aspirations wording differs from S11 pooled Tables3/A.11:0.07(SE0.05) and0.06 with corrected p=.44/.50. Final tables, definitions and pooled/arm-specific interpretation remain unverified; do not infer a changed published estimate or a positive pooled effect.','Final publication of same Zambia trial as S11, not independent evidence. Commute/absence rounding accords with S11 tables, whereas its opening abstract retained older35%/27% values. The aspirations narrative/table difference is unresolved, not explained by rounding.',abstract_url='https://academic.oup.com/ej/article-abstract/136/679/2531/8317231')
]
save('sources.json',sources)

cases=[]
def case(n,title,region,period,domain,outcome,summary,stages,mechanisms,counter,claims,source_ids,episode,actors,labour,**extra):
    cases.append(dict(id=f'PSY-C{n:02}',title=title,region=region,period=period,domain=domain,outcome=outcome,summary=summary,stages=stages,mechanisms=mechanisms,counterevidence=counter,claim_ids=[f'PSY-K{x:02}' for x in claims],source_ids=[f'PSY-S{x:02}' for x in source_ids],episode=episode,actors=actors,labour=labour,**extra))
case(1,'Harvest-timed fertilizer offers in Busia: use without persistent adoption',['Western Kenya; Busia district'],'2000–2005; primary offer experiment 2003–2005',['agriculture','behaviour','distribution'],['increased use during offer','nonpersistent use','dose-dependent profitability'],
 'Research-assisted dose trials and randomised offers show that the configuration and timing of access matter; neither every recommended input package nor a universal present-bias account follows.',
 {'feasibility':'On-farm trials establish output and calculated returns for specific CAN doses, not fertilizer generically.','deployment':'SAFI sold vouchers at market fertilizer prices with free delivery at specified times.','diffusion':'Household any-plot use rose during treatment seasons.','non-adoption/niche':'Many eligible farmers did not buy; treatment effects did not persist into later seasons absent renewed offers.'},
 ['timing of acquisition cost','seasonal resources','possible commitment/procrastination','agronomic dose fit'],
 'Late-delivery estimate +9–10pp is imprecise, not zero; early–late contrast p=.08. More intensive official package had negative mean calculated return. Timing-choice result does not fully fit authors’ simple model.',[1,2,3],[1,2],
 {'technology_configuration':'Maize top-dressing CAN, with dose experiments distinguished from market-price fertilizer vouchers and delivery offers.','task':'Raise maize returns and arrange purchase before top-dressing time.','population':'Dose trials: farmers sampled via school-parent lists. SAFI: 1,230 farmers sampled from parents of fifth/sixth graders in 16 schools; outcome covers any household plot, not just respondent-controlled plots.','interval':'Six agronomic seasons starting July 2000; primary SAFI offers for 2004 long/short rains and follow-up in 2005.','contemporary_alternatives':['No fertilizer or customary low input','Purchase fertilizer privately near application','Late free delivery','Late 50% subsidy','Early offer with chosen timing'],'adoption_measure':'Self-reported fertilizer use on any household plot by season. S01 Table 4 adjusted first-season effect +14.3pp against 24.0% comparison; adjusted second-season +18.1pp against about 26%. Denominators differ by season/controls (first-season full-controls N=716).','observation_limits':'Not a population diffusion curve; households without school-age pupils underrepresented; adoption data obtained for 924/1,230 sampled farmers (75.1%, S01 footnote10), with varying regression denominators and reporting limits; agronomic plots research-assisted.'},
 {'chooser':'Sampled farmer accepts or refuses offer; household plot decisions may involve spouses.','payer':'Farmer pays fertilizer price; NGO funds delivery/experiment and the subsidy arm.','operator_maintainer':'Farmer/household applies inputs; field staff assist agronomic trials and deliver vouchers/fertilizer.','affected_nonchooser':'Other household cultivators and members bear resource allocation and farm-work consequences.','ability_to_refuse':'Explicit voluntary purchase; nonpurchase observed; fertilizer ownership allowed resale, although few reported it. Household members’ bargaining and independent refusal not measured.'},
 {'tasks':'Input acquisition, transport, dose application, cultivation and harvest; delivery shifts a market trip to programme staff.','entry_barriers':'Cash/harvest resources, access to a market and plot, knowledge of dose; individual skill or land-access barriers not separately identified.','bargaining_ownership':'Private purchases and household plots; within-household control of gains not established.','transition':'Seasonal use observed; no permanent occupational transition followed.','distribution':'Dose-specific average returns and treatment averages; not effects on hired labour, landless people, wages or gendered task burdens.','evidence_limit':'Research-assisted plot profits and uptake cannot establish whole-farm livelihood gains or durable labour demand.'})
case(2,'Learning which seaweed input to observe in Nusa Penida',['Indonesia; Nusa Penida, Bali'],'2006–2008; main field experiment 2007–2008',['aquaculture','learning','attention'],['practice change after summaries','limited change after trials alone','continued established spacing'],
 'Farmers’ independently elicited knowledge differs by input dimension. A trial-plus-explanation package changes practices, but limited attention is not cleanly separated from computation, credibility or learning delay.',
 {'feasibility':'Existing seaweed farming; trials vary pod size and, in one arm, spacing.','deployment':'117 farmers participate in compensated on-plot experiments followed by personalised summaries.','diffusion':'Only short-run within-sample input changes measured; no population spread estimate.','non-adoption/niche':'Trial participation before summaries produced little detectable change; spacing practices largely persisted.'},
 ['selective attention hypothesis','interpretable feedback','computation assistance','experience-dependent beliefs'],
 'Summary arrives later for all treated farmers, with no separate randomisation of timing/content. Measured pod-size effect about 7g is imprecise; explanation can change perceived returns as well as attention.',[4,5,6],[3],
 {'technology_configuration':'Existing line-grown seaweed with pod size and spacing as distinct adjustable inputs; 65 sorting trials and 52 weight trials.','task':'Choose productive planting inputs on a farmer’s own plot.','population':'489 baseline respondents from a 2006 census of about 2,706 farmers in seven villages/24 hamlets; 117 randomly assigned trials; 232-person follow-up frame with 231 then 221 located.','interval':'Baseline June–December 2007; trials July 2007–March 2008; follow-ups April–May and July–August 2008, with summaries May–June.','contemporary_alternatives':['Continue customary cutting/spacing','Learn by observing raw trial measurements','Use personalised summary and discussion'],'adoption_measure':'Enumerator-measured pod weights/distances and self-reported changed techniques. Table IV contains 684 person-wave observations, not 684 independent farmers.','observation_limits':'Short follow-up and selection of active existing growers; paper’s projected income gains are not sustained realised income measurements.'},
 {'chooser':'Farm operator chooses subsequent inputs; assignment governs offer of researcher-managed trial.','payer':'Researchers provide trial inputs, guarantee a return floor and small time gift; farmer bears routine operating effort.','operator_maintainer':'Farmer and field team plant/weigh trial lines; subsequent cutting and cultivation remain farm tasks.','affected_nonchooser':'Household labour and buyers potentially affected; their outcomes not separately observed.','ability_to_refuse':'All approached trial farmers participated; voluntary context with compensation. Refusal by unpaid helpers or household members not measured.'},
 {'tasks':'Cutting, attaching, sorting, measuring and tending seaweed; summary interpretation adds a knowledge task.','entry_barriers':'Existing farming plots/lines and practical knowledge; no new occupational entrants studied.','bargaining_ownership':'Farm-level decisions observed; ownership and sale of output not tested as bargaining mechanisms.','transition':'Two short follow-ups; no occupational migration or sustained skill-premium evidence.','distribution':'Input-dimension and trial-type heterogeneity; no robust gender/wealth distribution of livelihood gains established.','evidence_limit':'Labour cost of precise cutting and time spent interpreting evidence were not isolated experimentally.'})
case(3,'Malawian agricultural communication: incentives, networks and gendered credibility',['Malawi; eight-district extension experiment and three-district network experiment'],'2009–2013, two explicitly separated experimental programmes',['agriculture','social learning','institutional design','gender'],['incentive-dependent diffusion','network targeting gains','measured credibility gap','substantial non-adoption'],
 'Public extension arrangements shape who communicates and receives attention. Targeting and incentives affect diffusion, but neither automatic peer imitation nor a uniform gender barrier to final uptake is established.',
 {'deployment':'Government extension officers train designated lead/peer farmers or two network-selected seeds.','diffusion':'Knowledge and observed/reported farming adoption followed over two or three seasons.','non-adoption/niche':'Non-incentivised dissemination often weak; benchmark network villages frequently show no non-seed adoption; most farmers remain non-adopters even with targeting.','scaling':'Expensive network mapping is a proof of concept, not a demonstrated cheap universal delivery system.'},
 ['costly communication effort','locally relevant demonstrations','network exposure','gendered perceived credibility'],
 'One versus five communicators confounds identity/coverage; S05/S06 share data. Network adoption-rate difference not significant in final year; reinforcement versus other multi-contact processes unresolved. Female-reserved roles yield poorer reception without a precise pooled downstream adoption/yield penalty.',[7,8,9,10],[4,5,6],
 {'technology_configuration':'Pit planting for maize moisture retention and crop-residue management; programmes and technologies kept separate where outcomes differ.','task':'Learn and disseminate cultivation methods through overstretched public extension.','population':'Programme A (S05/S06): 2009–11, eight districts; 120-village incentive/communicator analysis and overlapping 143-village gender-reservation analysis, rotating noncommunicator samples and separately interviewed spouses. Programme B (S04): 200 villages in Machinga, Mwanza, Nkhotakota, ~5,600 sampled households with network census covering >80% of households per village.','interval':'A: baseline 2009, follow-up 2010/2011. B: two or three annual rounds 2011–2013 depending on district.','contemporary_alternatives':['Extension officer alone','One locally selected lead farmer','Five ordinary peer communicators with/without rewards','Two seeds selected by extension officer','Two seeds selected using network or geographic algorithms','Continue ridging/flat planting or alternative residue use'],'adoption_measure':'A: knowledge exams, contact/training reports and physical farm-practice checks; B: seasonal pit-planting adoption and village indicator for any non-seed adoption. Compare exact denominators and seasons, not pooled effect size.','observation_limits':'Rotating respondents/partial panels; network and incentive designs distinct. Most farmers never adopt within observation; weather and soil suitability differ.'},
 {'chooser':'Ministry/researchers allocate communicator-selection rules; village meetings and officers select eligible people; each farmer decides subsequent practice.','payer':'Public extension and research programme support training and rewards; households provide cultivation resources.','operator_maintainer':'Extension officers, communicator farmers and household cultivators; communication is additional work.','affected_nonchooser':'Farm household members, unpaid workers and farmers not reached by extension.','ability_to_refuse':'Cultivation uptake not mandated; substantial non-adoption. Village role endorsement/selection documented; selected women’s within-household permission and cost of declining are not measured.'},
 {'tasks':'Demonstration, explaining and answering questions; digging/reusing planting pits, weeding and residue management.','entry_barriers':'Lead criteria included literacy/status/resources; peer criteria broader. No gender gap in measured learning among selected communicators; female-led training receives less attendance.','bargaining_ownership':'Performance rewards acknowledge communication labour; who controls household gains and unpaid burdens is not established.','transition':'Communicator effort and farm tasks tracked over 2–3 seasons; not an occupational career panel.','distribution':'S06 directly measures sex-specific reception and subgroup knowledge/adoption; broad aggregate equivalence not proven. S05 reports labour-time changes but not wage or employment distribution.','evidence_limit':'No estimate of economy-wide extension job substitution, female earnings gains or landless-worker losses.'},
 subepisodes=[{'label':'A: incentives and gender reservation','source_ids':['PSY-S05','PSY-S06'],'nonindependence':'Overlapping cross-cutting experiment; do not count as two replications.'},{'label':'B: network selection','source_ids':['PSY-S04'],'nonindependence':'Separate design; same institutional/research context, community overlap not independently audited.'}])
case(4,'Hearing aids: service fit, identity and the difference between trying and keeping',['United States; Indiana and San Francisco Bay Area'],'2004–2008 observational cohort; one-year dyad study published 2010; clinical trial November 2012–August 2016 (published 2017)',['assistive technology','hearing','accessibility','identity'],['improved hearing outcomes','different satisfaction/intention','device returns','heterogeneous stigma'],
 'Task benefit, usage, identity and retention are distinct. Controlled delivery evidence and independently elicited interviews support a multi-part explanation, while price-cohort and selection limitations block a universal stigma or cost account.',
 {'feasibility':'Same digital hearing-aid hardware tested with effective amplification versus acoustically transparent placebo.','deployment':'Volunteers use audiology best-practice or consumer-selected preset fittings.','non-adoption/niche':'Some eligible volunteers decline trial purchase; some purchasers return devices; some interviewees discount stigma.','displacement/reversal':'Returns within one-month or six-plus-week trial windows observed; not long-term national abandonment.'},
 ['acoustic/task fit','orientation and maintenance','subjective need','social meaning and supportive relations','price and selection'],
 'Price assigned sequentially, not randomly; wealthy/educated clinic volunteers not representative. Daily use does not distinguish the randomised arms despite differences in benefits. Qualitative stigma lacks causal identification and is not universal.',[11,12,13,14],[7,8,9,13],
 {'technology_configuration':'S07: same digital mini-behind-ear aids with audiology best practices, consumer choice among presets or placebo programming; S08: earlier clinical hearing-aid purchase cohort; S09: help-seeking dyads discussing assorted aids.','task':'Everyday speech communication, not a generic normal-hearing restoration or cognition intervention.','population':'S07: 163 enrolled/154 completers, target ages 55–79 and mild-to-moderate hearing loss, no prior aid use, English native language and cognitive eligibility; 98% White,78% college degree,80% income >$45,000. S08: 139 never-users aged 60–89 in selected analytic comparison, 105 purchasers/34 nonpurchasers. S09: 91 dyads, hearing-impaired member >=60, 90% White, 84 followed to one year.','interval':'S08 original recruitment 2004–08; S09 one-year follow-up with field calendar dates unspecified; S07 trial recruitment/data collection 2 November 2012–31 August 2016, with six-week primary trial and optional four-week extension, published 2017.','contemporary_alternatives':['No hearing aid or delayed purchase','Audiologist-selected/verified fitting with orientation','Consumer choice among preset aids','Communication adaptation by users/partners; not randomised as alternative'],'adoption_measure':'S07 speech/self-report benefit, satisfaction, datalogged daily hours, preliminary keep intention, later actual returns. S08 purchase decision and one-month returns. S09 narrated decisions and meanings; no population uptake denominator.','observation_limits':'Three distinct study populations; no pooled rate. Placebo trial and interview evidence address different questions. Severe loss, cognitive/dexterity barriers and Deaf identity not represented by these samples.'},
 {'chooser':'Adults elect trial participation and retention; service model randomised after consent. Dyad partners influence discussions but do not necessarily choose devices.','payer':'Trial participants pay device charge; research support covers trial infrastructure. In S07 typical/reduced prices occur sequentially.','operator_maintainer':'Wearer inserts/cleans devices and changes batteries; audiologists fit and troubleshoot; partners adapt communication.','affected_nonchooser':'Communication partners bear repetition, relationship and communication costs.','ability_to_refuse':'Nonparticipation and returns documented; consent and refund options available. Clinical recommendation does not establish a duty to adopt; constrained alternatives for severe impairment outside scope.'},
 {'tasks':'Audiometry, fitting, orientation, maintenance and user self-management; unpaid communication adaptation by partners.','entry_barriers':'Clinical credentials for providers; for users hearing configuration, cognition/language eligibility and payment. Severe dexterity barriers mostly excluded/unmeasured.','bargaining_ownership':'Users buy and can return aids; professional versus self-service tasks reorganised, not provider earnings measured.','transition':'Weeks to one year for use/decisions; no professional displacement or job-transition panel.','distribution':'Predominantly White selected older volunteers; lower-income, working-age and non-English users insufficiently covered.','evidence_limit':'No claim about labour-market benefits, optimal lifetime use, all assistive technologies or all deaf/hard-of-hearing people.'},
 subepisodes=[{'label':'Randomised service models','source_ids':['PSY-S07','PSY-S13']},{'label':'Earlier volunteer nonpurchase/return analysis','source_ids':['PSY-S08']},{'label':'Independent qualitative meanings','source_ids':['PSY-S09']}])
case(5,'Bicycles and girls’ schooling: distinct Bihar and Zambia institutional packages',['India; Bihar with Jharkhand comparator','Zambia; Monze, Mazabuka, Kalomo districts'],'Bihar 2006–2008 with later exam checks; Zambia 2017–2021',['transport','education','gender','accessibility'],['higher age-appropriate enrolment','shorter commute and better attendance','bounded agency gains','continued constraints'],
 'Two explicitly separate school-access episodes show that finance, infrastructure, maintenance and gendered circumstances jointly shape mobility. Neither identifies a universal psychological effect of a bicycle or of paying for it.',
 {'deployment':'Bihar cash earmarked for bicycle purchase; Zambia distributed bikes with mechanics, monitoring and school-use custody conditions.','diffusion':'Bihar programme exposure affects grade-age enrolment; Zambia randomised school offer affects access, travel and attendance. These are not comparable bike-ownership diffusion curves.','non-adoption/niche':'Those outside school/distance eligibility are largely unobserved; distant girls retain constraints; several agency and educational outcomes have null/imprecise effects.','scaling':'Bihar is statewide programme evaluation; Zambia is a 100-school trial. No extrapolated national saturation claim.'},
 ['reduced travel burden','conditional asset access','physical infrastructure','household allocation','possible safety/agency feedback'],
 'Bihar schooling/safety reforms and roads are rival/complementary processes; norm change not separately measured. Road proxy is imperfect/nonrandom. In the May2025 Zambia manuscript, fee/free-arm differences and pooled general mobility/aspirations are imprecise while selected reported agency outcomes improve. The final abstract says educational aspirations improved; final tables/definitions and pooled-versus-arm-specific interpretation were not inspected, so this difference remains unresolved.',[15,16,17,18,19,20],[10,11,12,14],
 {'technology_configuration':'Bihar: Rs2,000 earmarked grant after grade-9 enrolment, school receipt certification. Zambia: durable bicycle plus trained mechanic, supervisory committee and four-year resale prohibition, with randomised $5 maintenance-fee versus free variants.','task':'Access school and reduce commuting burdens for adolescent girls; ownership and broader mobility are separate outcomes.','population':'Bihar: DLHS-3 household members age14–17, treated age14–15 versus16–17, girls versus boys, Bihar versus Jharkhand; full-control main Table2 N=30,112. Zambia: 100 public basic schools, initially enrolled grade5–7 girls walking >3km away; urban and some very remote schools excluded. 25 payment, 20 free, 55 control schools. Survey frame2,471; Table1 commute N=1,879 and Table4 attendance N=1,952.','interval':'Bihar grant launched June2006; DLHS late2007/early2008. Zambia baseline July–August2017, distribution September–November2017, follow-up October–December2018, administrative follow-up2019–21.','contemporary_alternatives':['Walking to existing school','Do not enrol or discontinue schooling','Other transport where available, not a uniform available substitute','School construction/relocation not randomised in these studies','Zambia otherwise identical bike package with/without nominal fee'],'adoption_measure':'Bihar age-appropriate enrolment/completion proxy from policy exposure (+5.2pp in main adjusted estimate), not measured riding. Zambia self-reported access, minutes one-way and days absent/late last week, plus agency indices; later administrative retention/attendance conditional samples separate.','observation_limits':'No pooled effect/denominator. Bihar triple-difference assumptions; Zambia differential attrition and self-report, later administrative data not preregistered. Final Zambia full text not acquired: detailed evidence from May2025 manuscript; its imprecise pooled aspirations differ from the final abstract’s positive assertion, unresolved until final tables/definitions are inspected. Disability/cycling-ability representation and route accessibility not established; no such exclusion rule identified in inspected sampling passages.'},
 {'chooser':'Governments/NGO define eligibility and conditions; households choose Bihar purchase/type; Zambia girls/guardians accept allocated bikes and girls operate them subject to family and school rules.','payer':'Bihar state funds grant; households may cover extras/maintenance. Zambia programme funds bicycles/support; treatment families pay nominal maintenance fee only in payment arm.','operator_maintainer':'Girls ride; families share some use; Bihar local repair arrangements unmeasured; Zambia school-linked trained mechanics support repair.','affected_nonchooser':'Household members, excluded/out-of-school girls, siblings and school staff; sharing and monitoring can redistribute resources/control.','ability_to_refuse':'Zambia refusal reported but almost universal take-up among eligible recipients; primary-school use and resale restrictions limit subsequent choice. Bihar household discretion/receipt conditions documented; adolescent bargaining or independent refusal not fully measured.'},
 {'tasks':'Travel time shifts; bicycle repair/supervision tasks; household asset-sharing. Zambia Table2 lower odds of girls’ income-generating time but no clear changes in most other reported time categories.','entry_barriers':'Documented Zambia eligibility is school enrolment in grades5–7 and walking distance; school sampling excludes urban and some very remote schools. Disability, cycling capacity and route accessibility are unmeasured applicability limits here, not established eligibility rules; household permission may constrain use.','bargaining_ownership':'Bihar grant earmarked to eligible girls; Zambia conditional custodianship and household sharing. Selected self-reported bargaining improves, not unrestricted asset control.','transition':'School outcomes followed up to four years; adult employment, wages and occupation transitions not established.','distribution':'Gender targeted; distance heterogeneity and imperfect road-connected comparisons. Out-of-school/noneligible girls outside Zambia target; disability/cycling-ability representation and corresponding outcomes not established.','evidence_limit':'School participation or agency scores cannot be converted into future earnings, occupational access or universal emancipation.'},
 subepisodes=[{'label':'Bihar quasi-experiment','population':'Age14–17 Bihar/Jharkhand cohorts; no pooled Zambia denominator.','source_ids':['PSY-S10','PSY-S12']},{'label':'Zambia school-randomised comparison','population':'Initially enrolled grade5–7 girls >3km from100 schools.','source_ids':['PSY-S11','PSY-S14']}])
