edges=[]
def edge(n,a,b,rel,c,ks,ss,conf,qualification,basis,stage,config,alts,dispute):
    edges.append(dict(id=f'PSY-E{n:02}',**{'from':f'PSY-T{a:02}','to':f'PSY-T{b:02}'},relation=rel,case_ids=[f'PSY-C{c:02}'],claim_ids=[f'PSY-K{k:02}' for k in ks],source_ids=[f'PSY-S{s:02}' for s in ss],confidence=conf,qualification=qualification,basis=basis,scope=dict(case_id=f'PSY-C{c:02}',stage=stage,configuration=config),alternatives=alts,joint_inputs=[],necessity_rationale='No necessity claim',dispute=dispute))
