comparisons=[
 dict(id='PSY-X01',question='Does one induced use create a self-sustaining habit or learning transition?',case_ids=['PSY-C01','PSY-C02'],useful_similarities='Existing small producers can alter granular inputs; both have randomised field exposure and subsequent behaviour measures.',important_differences='Kenya changes acquisition timing and resources; Indonesia changes experimental information/interpretation. Seasonal fertilizer versus repeated seaweed input choices.',evidence_comparability='No common treatment or follow-up horizon. Kenya reports household any-plot use; Indonesia measures input size and self-reported practice.',connections_nonindependence='Different original datasets/countries; shared development-economics conceptual literature, and S03 explicitly discusses Duflo/Kremer/Robinson.',omitted_countercases='Long-term autonomous adoption after one learning episode; major new technologies with irreversible fixed investment.',conclusion_limit='Kenya’s lack of persistence and seaweed’s phase-dependent change reject a generic automatic-habit story; they do not imply the same psychology or permanent non-adoption.'),
 dict(id='PSY-X02',question='Is making information available enough, or must communication and interpretation be produced?',case_ids=['PSY-C02','PSY-C03'],useful_similarities='Both directly measure knowledge/practices rather than using uptake alone; extension and demonstrations present.',important_differences='Seaweed farmer’s own trial versus Malawian social transmission; pod-size adjustment versus pit planting/CRM; individual versus village randomisation.',evidence_comparability='No pooled effect: numerical comprehension, knowledge exams, network contact and adoption are distinct measures.',connections_nonindependence='Shared theoretical literature and some overlapping scholarly networks; Malawi S05/S06 share data, S04 separate design.',omitted_countercases='Self-taught innovations, informal networks without formal extension, technologies requiring little learning.',conclusion_limit='Information interpretation and transmission are tasks with incentives/costs. Neither evidence establishes attention or reinforcement as the exclusive cognitive mechanism.'),
 dict(id='PSY-X03',question='When does identity-based reception matter independently of measured technical competence?',case_ids=['PSY-C03','PSY-C04'],useful_similarities='Malawi elicits recipient ratings and competence separately; hearing dyads independently describe meanings before/after decisions.',important_differences='Randomised role reservation changes messenger composition; qualitative stigma study follows selected help-seekers and partners. Gendered adviser credibility differs from an older user’s self-presentation.',evidence_comparability='Ratings/attendance, audiology benefits and narratives cannot be pooled. Aggregate Malawi diffusion penalty is imprecise; Bay Area stigma effect not identified.',connections_nonindependence='Distinct datasets and institutional settings; within hearing evidence S07/S13 are one trial and correction.',omitted_countercases='Deaf cultural identification, working-age assistive users, contexts where women are accepted agricultural authorities.',conclusion_limit='Social meaning is documented and heterogeneous, not inferred solely from uptake. Neither universal identity costs nor necessarily lower final adoption follow.'),
 dict(id='PSY-X04',question='What can price comparisons actually tell us about adoption motives?',case_ids=['PSY-C01','PSY-C04','PSY-C05'],useful_similarities='Fertilizer subsidies, hearing-device charges and bicycle maintenance fees all change what a potential user pays.',important_differences='Kenya randomises offer/timing/subsidy; hearing-aid price is sequential-cohort; Zambia randomises a single nominal fee on a largely subsidised package.',evidence_comparability='Cannot compare demand elasticities. Fertilizer use, trial benefit/returns and bicycle school participation use different populations/denominators.',connections_nonindependence='Separate datasets. Zambia manuscript/final abstract are one study, not two fee experiments.',omitted_countercases='Large fees excluding poorer nonparticipants, unsubsidised durable-goods markets, debt-financed adoption.',conclusion_limit='No general victory of psychological over price explanations. An insignificant price association or between-arm contrast is not price irrelevance or proven equivalence.'),
 dict(id='PSY-X05',question='Do the Bihar and Zambia bicycle episodes isolate emancipation, or particular school-access packages?',case_ids=['PSY-C05'],useful_similarities='Girls face distance-related school access constraints; bicycles supplied through institutions; distance heterogeneity matters.',important_differences='Bihar earmarked purchase money at secondary-school entry; Zambia direct provision to already-enrolled grade5–7 girls>3km away with mechanics, committees and custody restrictions. Bihar quasi-experiment versus Zambia school randomisation.',evidence_comparability='Bihar age-appropriate grade9 participation is not Zambia last-week attendance. Zambia measures agency directly; Bihar norms mostly interpretive. No pooled percentage.',connections_nonindependence='One shared author and conceptual connection, separate countries/datasets. Road reanalysis S12 reuses Bihar policy and DLHS-3. S11/S14 are draft/final of same Zambia trial.',omitted_countercases='Zambia omits out-of-school girls, urban schools and some very remote schools by sampling. Disability/cycling-ability representation and outcomes under inaccessible routes or extreme distances remain unestablished; unrestricted cash versus bike grants not tested.',conclusion_limit='Evidence supports bounded access benefits and selected reported agency changes. Roads/maintenance may contribute; neither strict road necessity nor universal norm change is identified.')
]
